"use client";

import * as React from "react";
import type { DictionaryNamespace } from "@/lib/i18n/i18n";
import type { AppSidebarConfig } from "./types";

declare global {
  interface FmaNamespaces {
    appSidebar: AppSidebarConfig;
  }
}

export const appSidebarEn: DictionaryNamespace<AppSidebarConfig> = {
  labels: {
    opensInNewTab: "opens in new tab",
    team: "Team",
    teams: "Teams",
    account: "Account",
  },
};

/** The block's own texts, in the active language; `AppSidebar` provides them. */
export const AppSidebarLabelsContext = React.createContext(appSidebarEn.labels);

"use client";

import type * as React from "react";
import { Sidebar, SidebarRail } from "@/core/sidebar/sidebar";
import { type NamespaceOverrides, useFmaMessages } from "@/lib/i18n/i18n";
import { AppSidebarLabelsContext, appSidebarEn } from "./app-sidebar-labels";
import type { AppSidebarConfig } from "./types";

type AppSidebarProps = React.ComponentProps<typeof Sidebar> & {
  i18n?: NamespaceOverrides<AppSidebarConfig>;
};

/**
 * App-shell sidebar (shadcn "sidebar-07"), collapsible to icons. Compose it from the core's
 * `SidebarHeader`, `SidebarContent` and `SidebarFooter`, with the parts below. Render it inside a
 * `SidebarProvider`.
 */
export function AppSidebar({ i18n, children, ...props }: AppSidebarProps) {
  const { labels } = useFmaMessages("appSidebar", appSidebarEn, i18n);
  return (
    <Sidebar collapsible="icon" {...props}>
      <AppSidebarLabelsContext.Provider value={labels}>{children}</AppSidebarLabelsContext.Provider>
      <SidebarRail />
    </Sidebar>
  );
}

export { appSidebarEn } from "./app-sidebar-labels";
export { AppSidebarItem, AppSidebarSection, AppSidebarSubItem } from "./nav-items";
export { AppSidebarUser } from "./nav-user";
export { AppSidebarLogo, AppSidebarTeam, AppSidebarTeamSwitcher } from "./team-switcher";
export type * from "./types";
export type { AppSidebarProps };

import type { AppSidebarItemAccess, AppSidebarItemBadge } from "./types";

/** The title with the badge, for texts that stand for the whole item. */
export function itemLabel({ title, badge }: { title: string; badge?: AppSidebarItemBadge }) {
  return badge ? `${title}, ${badge.label}` : title;
}

/** A blocked item goes nowhere, so it isn't a link at all. */
export function externalLinkProps({
  external,
  access,
}: {
  external?: boolean;
  access?: AppSidebarItemAccess["access"];
}) {
  return external && access !== "blocked"
    ? ({ target: "_blank", rel: "noopener noreferrer" } as const)
    : {};
}

import { cn } from "cn";
import { ExternalLinkIcon } from "lucide-react";
import { Badge } from "@/core/badge/badge";
import { externalLinkProps } from "./nav-access";
import type { AppSidebarItemAccess, AppSidebarItemBadge } from "./types";

// A sidebar can be as strong as the primary color, so a badge can't use the page's tints: each
// variant reads on any sidebar. `tests/app-sidebar-badge-contrast.test.ts` measures them. `ghost`
// has no surface of its own, so it follows the item, which also turns it on hover.
export const VARIANT_BADGE = {
  ghost: "border-transparent px-0",
  outline: "border-sidebar-foreground bg-sidebar text-sidebar-foreground",
  primary: "bg-sidebar-primary text-sidebar-primary-foreground",
  invert: "bg-sidebar-foreground text-sidebar",
} as const;

// A menu opens on the popover, so the sidebar's colors don't apply there. A focused item recolors
// its content, but a badge with a surface keeps its text: that's `!` and `**:text-inherit!`.
export const VARIANT_MENU_BADGE = {
  ghost: "border-transparent px-0 text-popover-foreground",
  outline: "border-popover-foreground bg-popover text-popover-foreground!",
  primary: "bg-sidebar-primary text-sidebar-primary-foreground!",
  invert: "bg-popover-foreground text-popover!",
} as const;

// The ring keeps a dot visible on any sidebar.
export const VARIANT_DOT = {
  ghost: "bg-sidebar ring-1 ring-sidebar-foreground",
  outline: "bg-sidebar ring-1 ring-sidebar-foreground",
  primary: "bg-sidebar-primary ring-1 ring-sidebar-foreground",
  invert: "bg-sidebar-foreground ring-1 ring-sidebar-foreground",
} as const;

const DEFAULT_VARIANT = { granted: "outline", blocked: "ghost", gated: "invert" } as const;

type NavItemStatusProps = {
  access?: AppSidebarItemAccess["access"];
  badge?: AppSidebarItemBadge;
  external?: boolean;
  /** Read after the title on an external link. */
  externalLabel?: string;
  /** Marks the item with a dot while the sidebar is collapsed to icons. */
  withDot?: boolean;
  /** Rendered in a menu, on the popover instead of the sidebar. */
  inMenu?: boolean;
};

/**
 * What the item says after its title. The screen reader text is one element in every layout: the
 * badge leaves the page when the sidebar collapses, and it would take the reason with it.
 */
export function NavItemStatus({
  access,
  badge,
  external,
  externalLabel,
  withDot = false,
  inMenu = false,
}: NavItemStatusProps) {
  const isExternal = externalLinkProps({ external, access }).target !== undefined;
  if (!badge && !isExternal) return null;

  const variant = badge?.variant ?? DEFAULT_VARIANT[access ?? "granted"];
  return (
    <>
      {badge && <span className="sr-only">{` ${badge.label}`}</span>}
      {isExternal && <span className="sr-only">{` ${externalLabel}`}</span>}
      <span
        aria-hidden="true"
        className="ml-auto flex shrink-0 items-center gap-2 group-data-[collapsible=icon]:hidden"
      >
        {badge && (
          <Badge
            variant={null}
            size="xs"
            className={cn(
              inMenu ? [VARIANT_MENU_BADGE[variant], "**:text-inherit!"] : VARIANT_BADGE[variant],
              // A blocked item dims its title, but the reason has to stay legible.
              !inMenu && variant === "ghost" && access === "blocked" && "text-sidebar-foreground",
              "[&_svg]:size-2.5!",
            )}
          >
            {badge.icon}
            {badge.label}
          </Badge>
        )}
        {isExternal && (
          <ExternalLinkIcon className="size-2.5! opacity-60 transition-opacity in-[a:focus]:opacity-100 in-[a:hover]:opacity-100" />
        )}
      </span>
      {badge && withDot && (
        <span
          aria-hidden="true"
          className={cn(
            "absolute top-1 right-1 hidden size-1.5 rounded-full group-data-[collapsible=icon]:block",
            VARIANT_DOT[variant],
          )}
        />
      )}
    </>
  );
}

"use client";

import { ChevronRightIcon, MoreHorizontalIcon } from "lucide-react";
import * as React from "react";
import { Collapsible, CollapsibleContent } from "@/core/collapsible/collapsible";
import {
  DropdownMenu,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/core/dropdown-menu/dropdown-menu";
import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
  useSidebar,
} from "@/core/sidebar/sidebar";
import { AppSidebarLabelsContext } from "./app-sidebar-labels";
import { externalLinkProps, itemLabel } from "./nav-access";
import { NavItemStatus } from "./nav-item-status";
import type { AppSidebarItemProps, AppSidebarSectionProps, AppSidebarSubItemProps } from "./types";

/** A sub-item's parent decides what it renders as: a sidebar row, or a menu item. */
const SubItemPlacementContext = React.createContext<"sidebar" | "menu">("sidebar");

const isEmpty = (children: React.ReactNode) => React.Children.toArray(children).length === 0;

/** A section of the sidebar. It isn't rendered without items. */
export function AppSidebarSection({ title, children }: AppSidebarSectionProps) {
  if (isEmpty(children)) return null;
  return (
    <SidebarGroup>
      <SidebarGroupLabel>{title}</SidebarGroupLabel>
      <SidebarMenu>{children}</SidebarMenu>
    </SidebarGroup>
  );
}

/**
 * With `children`, a `granted` item opens its sub-items, and isn't rendered without any. Any other
 * access ignores them: a `gated` item follows its target, and a `blocked` one goes nowhere.
 */
export function AppSidebarItem(props: AppSidebarItemProps) {
  const { isMobile, state } = useSidebar();
  const isIconCollapsed = state === "collapsed" && !isMobile;

  const isGranted = (props.access ?? "granted") === "granted";
  // JSX passes `children` even when the only child is `undefined`: that's an empty parent.
  if (!isGranted || !("children" in props)) return <LeafItem {...props} />;
  if (isEmpty(props.children)) return null;
  // Icon-only sidebars have no room for inline sub-items.
  const variant = isIconCollapsed ? "dropdown" : (props.variant ?? "collapse");
  return variant === "dropdown" ? (
    <DropdownItem {...props} withLabel={isIconCollapsed} />
  ) : (
    <CollapseItem {...props} />
  );
}

function LeafItem({
  title,
  href,
  onPress,
  icon,
  isActive,
  external,
  access,
  badge,
}: AppSidebarItemProps) {
  const { opensInNewTab: externalLabel } = React.useContext(AppSidebarLabelsContext);
  const isBlocked = access === "blocked";
  const isCurrent = isActive && !isBlocked;
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        {...(href === undefined
          ? { onPress }
          : { href, ...externalLinkProps({ external, access }) })}
        isInactive={isBlocked}
        isActive={isCurrent}
        aria-current={isCurrent ? "page" : undefined}
        tooltip={itemLabel({ title, badge })}
      >
        {icon}
        <span className="truncate">{title}</span>
        <NavItemStatus
          access={access}
          badge={badge}
          external={external}
          externalLabel={externalLabel}
          withDot
        />
      </SidebarMenuButton>
    </SidebarMenuItem>
  );
}

function CollapseItem({ title, icon, isActive, badge, children }: AppSidebarItemProps) {
  return (
    <SidebarMenuItem>
      <Collapsible defaultExpanded={isActive} className="group/collapsible">
        <SidebarMenuButton slot="trigger" tooltip={itemLabel({ title, badge })}>
          {icon}
          <span className="flex-1 truncate">{title}</span>
          <NavItemStatus badge={badge} withDot />
          <ChevronRightIcon
            aria-hidden="true"
            className="ml-auto shrink-0 transition-transform duration-200 group-data-expanded/collapsible:rotate-90"
          />
        </SidebarMenuButton>
        <CollapsibleContent>
          <SidebarMenuSub className="mr-0 pr-0">{children}</SidebarMenuSub>
        </CollapsibleContent>
      </Collapsible>
    </SidebarMenuItem>
  );
}

function DropdownItem({
  title,
  icon,
  badge,
  children,
  withLabel,
}: AppSidebarItemProps & { withLabel: boolean }) {
  const { isMobile } = useSidebar();
  return (
    <SidebarMenuItem>
      <DropdownMenuTrigger>
        <SidebarMenuButton
          tooltip={itemLabel({ title, badge })}
          className="aria-expanded:bg-sidebar-accent aria-expanded:text-sidebar-accent-foreground"
        >
          {icon}
          <span className="flex-1 truncate">{title}</span>
          <NavItemStatus badge={badge} withDot />
          <MoreHorizontalIcon aria-hidden="true" className="ml-auto shrink-0" />
        </SidebarMenuButton>
        <SubItemPlacementContext.Provider value="menu">
          <DropdownMenu
            aria-label={title}
            placement={isMobile ? "bottom start" : "end top"}
            className="w-fit min-w-40"
          >
            {withLabel && (
              <>
                <DropdownMenuLabel>{title}</DropdownMenuLabel>
                <DropdownMenuSeparator />
              </>
            )}
            {children}
          </DropdownMenu>
        </SubItemPlacementContext.Provider>
      </DropdownMenuTrigger>
    </SidebarMenuItem>
  );
}

/** Each sub-item has its own access, inline or in a menu. */
export function AppSidebarSubItem({
  title,
  href,
  onPress,
  icon,
  external,
  access,
  badge,
}: AppSidebarSubItemProps) {
  const placement = React.useContext(SubItemPlacementContext);
  const { opensInNewTab: externalLabel } = React.useContext(AppSidebarLabelsContext);
  const isBlocked = access === "blocked";
  const inMenu = placement === "menu";
  const content = (
    <>
      {icon}
      <span className="truncate">{title}</span>
      <NavItemStatus
        access={access}
        badge={badge}
        external={external}
        externalLabel={externalLabel}
        inMenu={inMenu}
      />
    </>
  );
  if (!inMenu) {
    return (
      <SidebarMenuSubItem>
        <SidebarMenuSubButton
          {...(href === undefined
            ? { onPress }
            : { href, ...externalLinkProps({ external, access }) })}
          isInactive={isBlocked}
          className="w-full"
        >
          {content}
        </SidebarMenuSubButton>
      </SidebarMenuSubItem>
    );
  }
  // A disabled menu item can't take focus, and the reason would be out of reach.
  return isBlocked ? (
    <DropdownMenuItem
      textValue={itemLabel({ title, badge })}
      shouldCloseOnSelect={false}
      className="text-muted-foreground"
    >
      {content}
    </DropdownMenuItem>
  ) : (
    <DropdownMenuItem
      href={href}
      onAction={onPress}
      textValue={itemLabel({ title, badge })}
      {...externalLinkProps({ external, access })}
    >
      {content}
    </DropdownMenuItem>
  );
}

"use client";

import { ChevronsUpDownIcon } from "lucide-react";
import * as React from "react";
import { Avatar, AvatarFallback, AvatarImage } from "@/core/avatar/avatar";
import {
  DropdownMenu,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/core/dropdown-menu/dropdown-menu";
import {
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/core/sidebar/sidebar";
import { AppSidebarLabelsContext } from "./app-sidebar-labels";
import type { AppSidebarUserProps } from "./types";

function initials(name: string) {
  return name
    .split(/\s+/)
    .slice(0, 2)
    .map((word) => word[0]?.toUpperCase() ?? "")
    .join("");
}

function UserSummary({ name, email, avatar }: Omit<AppSidebarUserProps, "children">) {
  return (
    <>
      <Avatar>
        {avatar && <AvatarImage src={avatar} alt="" />}
        <AvatarFallback>{initials(name)}</AvatarFallback>
      </Avatar>
      <div className="grid flex-1 text-left text-sm leading-tight">
        <span className="truncate font-medium">{name}</span>
        <span className="truncate text-xs">{email}</span>
      </div>
    </>
  );
}

/** The account in the footer: pass the menu's entries as `children`. */
export function AppSidebarUser({ name, email, avatar, children }: AppSidebarUserProps) {
  const { isMobile } = useSidebar();
  const labels = React.useContext(AppSidebarLabelsContext);
  const summary = <UserSummary name={name} email={email} avatar={avatar} />;
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenuTrigger>
          <SidebarMenuButton
            size="lg"
            aria-label={`${labels.account}: ${name}`}
            className="aria-expanded:bg-sidebar-accent aria-expanded:text-sidebar-accent-foreground"
          >
            {summary}
            <ChevronsUpDownIcon aria-hidden="true" className="ml-auto size-4" />
          </SidebarMenuButton>
          <DropdownMenu
            placement={isMobile ? "bottom end" : "end bottom"}
            className="w-fit min-w-56"
          >
            <DropdownMenuGroup>
              <DropdownMenuLabel className="flex items-center gap-2 px-1 py-1.5 font-normal text-foreground">
                {summary}
              </DropdownMenuLabel>
            </DropdownMenuGroup>
            <DropdownMenuSeparator />
            {children}
          </DropdownMenu>
        </DropdownMenuTrigger>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";

import { ChevronsUpDownIcon } from "lucide-react";
import * as React from "react";
import {
  DropdownMenu,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/core/dropdown-menu/dropdown-menu";
import {
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/core/sidebar/sidebar";
import { AppSidebarLabelsContext } from "./app-sidebar-labels";
import type {
  AppSidebarLogoProps,
  AppSidebarTeamProps,
  AppSidebarTeamSwitcherProps,
} from "./types";

/** The header's static alternative to a team switcher. */
export function AppSidebarLogo({ full, collapsed }: AppSidebarLogoProps) {
  // Same footprint as the switcher button, so collapsing behaves alike.
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <div
          data-slot="app-sidebar-logo"
          className="flex h-12 w-full items-center justify-center overflow-hidden rounded-md group-data-[collapsible=icon]:size-8!"
        >
          <div className="flex size-full items-center justify-center group-data-[collapsible=icon]:hidden">
            {full}
          </div>
          <div className="hidden size-full items-center justify-center group-data-[collapsible=icon]:flex">
            {collapsed}
          </div>
        </div>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

/** The app holds `activeTeam`: pass the entries as `children`, its own ones included. */
export function AppSidebarTeamSwitcher({ activeTeam, children }: AppSidebarTeamSwitcherProps) {
  const { isMobile } = useSidebar();
  const labels = React.useContext(AppSidebarLabelsContext);
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenuTrigger>
          <SidebarMenuButton
            size="lg"
            aria-label={`${labels.team}: ${activeTeam.name}`}
            className="aria-expanded:bg-sidebar-accent aria-expanded:text-sidebar-accent-foreground"
          >
            <div className="flex aspect-square size-8 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground">
              {activeTeam.logo}
            </div>
            <div className="grid flex-1 text-left text-sm leading-tight">
              <span className="truncate font-medium">{activeTeam.name}</span>
              <span className="truncate text-xs">{activeTeam.plan}</span>
            </div>
            <ChevronsUpDownIcon aria-hidden="true" className="ml-auto" />
          </SidebarMenuButton>
          <DropdownMenu
            placement={isMobile ? "bottom start" : "end top"}
            className="w-fit min-w-56"
          >
            <DropdownMenuLabel>{labels.teams}</DropdownMenuLabel>
            {children}
          </DropdownMenu>
        </DropdownMenuTrigger>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

/** One team in `AppSidebarTeamSwitcher`. */
export function AppSidebarTeam({ name, logo, onAction }: AppSidebarTeamProps) {
  return (
    <DropdownMenuItem textValue={name} onAction={onAction} className="gap-2 p-2">
      <div className="flex size-6 items-center justify-center rounded-md border">{logo}</div>
      {name}
    </DropdownMenuItem>
  );
}

import type * as React from "react";

/**
 * Contract of the `app-sidebar` block: it's composed, so these are the props of
 * its parts. What's atomic stays a prop; what the app lists goes in `children`.
 */

export type AppSidebarTeamSummary = {
  name: string;
  logo: React.ReactNode;
  plan: string;
};

export type AppSidebarTeamSwitcherProps = {
  activeTeam: AppSidebarTeamSummary;
  children?: React.ReactNode;
};

export type AppSidebarTeamProps = {
  name: string;
  logo: React.ReactNode;
  /** Unused here, so a team's whole object can be spread on it. */
  plan?: string;
  onAction?: () => void;
};

/**
 * `full` shows while the sidebar is expanded (and on mobile); `collapsed`
 * while it's retracted to icons. Swapped with CSS only.
 */
export type AppSidebarLogoProps = {
  full: React.ReactNode;
  collapsed: React.ReactNode;
};

export type AppSidebarUserProps = {
  name: string;
  email: string;
  avatar?: string;
  children?: React.ReactNode;
};

/** The text comes from the app, like `title`. */
export type AppSidebarItemBadge = {
  label: string;
  /**
   * `ghost` has no surface and follows the item's color, `outline` has a border, `primary` uses the
   * sidebar's primary color and `invert` inverts the sidebar. Defaults to `invert` on `gated`,
   * `ghost` on `blocked`, or `outline`.
   */
  variant?: "ghost" | "outline" | "primary" | "invert";
  icon?: React.ReactNode;
};

/**
 * An item goes somewhere or runs something. A `href` is a link: an app route, or any URL, which
 * `external` opens in a new tab. An `onPress` makes it a button.
 */
type AppSidebarItemTarget =
  | { href: string; external?: boolean; onPress?: never }
  | { onPress: () => void; href?: never; external?: never };

/**
 * What the item does; `badge` says why. To hide an item, don't render it.
 * - `granted` (default): follows its target.
 * - `blocked`: visible and focusable, goes nowhere. Requires a badge with the reason, and accepts a
 *   target it won't use, so `access` can change alone.
 * - `gated`: follows its target, which the app points at what resolves it (activate, upgrade, pay).
 *   Informative only: the app must guard the route.
 */
export type AppSidebarItemAccess =
  | ({ access?: "granted"; badge?: AppSidebarItemBadge } & AppSidebarItemTarget)
  | ({ access: "gated"; badge: AppSidebarItemBadge } & AppSidebarItemTarget)
  | {
      access: "blocked";
      badge: AppSidebarItemBadge;
      href?: string;
      external?: boolean;
      onPress?: () => void;
    };

export type AppSidebarSectionProps = {
  title: string;
  children?: React.ReactNode;
};

/**
 * Links are react-aria `Link`s: wrap the app in react-aria's `RouterProvider`
 * to route them client-side.
 */
export type AppSidebarSubItemProps = {
  title: string;
  icon?: React.ReactNode;
} & AppSidebarItemAccess;

/**
 * `variant` picks how a `granted` item opens its `children`: `"collapse"` (default) expands them
 * inline, `"dropdown"` opens a menu beside the item. While the sidebar is collapsed to icons every
 * item uses the dropdown. That item only opens them, so it needs no target and ignores one.
 */
export type AppSidebarItemProps = {
  title: string;
  icon?: React.ReactNode;
  /** Marks the current page and starts a collapse item expanded. */
  isActive?: boolean;
  variant?: "collapse" | "dropdown";
} & (
  | (AppSidebarItemAccess & { children?: React.ReactNode })
  | {
      access?: "granted";
      badge?: AppSidebarItemBadge;
      href?: undefined;
      external?: undefined;
      onPress?: undefined;
      children: React.ReactNode;
    }
  | {
      access: "granted" | "blocked";
      badge: AppSidebarItemBadge;
      href?: undefined;
      external?: undefined;
      onPress?: undefined;
      children: React.ReactNode;
    }
);

export type AppSidebarConfig = {
  labels: { opensInNewTab: string; team: string; teams: string; account: string };
};
